class Solution {
public:
    long long maximumValueSum(vector<vector<int>>& board) {
        int m = board.size();
        int n = board[0].size();
        vector<vector<pair<int, int>>> row_top3(m);
        for (int r = 0; r < m; ++r) {
            vector<pair<int, int>> row;
            for (int c = 0; c < n; ++c) {
                row.push_back({board[r][c], c});
            }
            sort(row.rbegin(), row.rend());
            row.resize(3);
            row_top3[r] = row;
        }
        long long max_sum = -1e18;
        for (int r1 = 0; r1 < m; ++r1) {
            for (int r2 = r1 + 1; r2 < m; ++r2) {
                for (int r3 = r2 + 1; r3 < m; ++r3) {
                    for (const auto& [v1, c1] : row_top3[r1]) {
                        for (const auto& [v2, c2] : row_top3[r2]) {
                            if (c2 == c1) continue;
                            for (const auto& [v3, c3] : row_top3[r3]) {
                                if (c3 == c1 || c3 == c2) continue;
                                max_sum = max(max_sum, 1LL * v1 + v2 + v3);
                            }
                        }
                    }
                }
            }
        }
        return max_sum;
    }
};

class Solution {
    public long maximumValueSum(int[][] board) {
        int m = board.length;
        int n = board[0].length;
        int[][][] rowTop3 = new int[m][3][2];
        for (int r = 0; r < m; ++r) {
            List<int[]> row = new ArrayList<>();
            for (int c = 0; c < n; ++c) {
                row.add(new int[]{board[r][c], c});
            }
            row.sort((a, b) -> Integer.compare(b[0], a[0]));
            for (int i = 0; i < 3; ++i) {
                rowTop3[r][i] = row.get(i);
            }
        }
        long maxSum = Long.MIN_VALUE;
        for (int r1 = 0; r1 < m; ++r1) {
            for (int r2 = r1 + 1; r2 < m; ++r2) {
                for (int r3 = r2 + 1; r3 < m; ++r3) {
                    for (int[] p1 : rowTop3[r1]) {
                        for (int[] p2 : rowTop3[r2]) {
                            if (p2[1] == p1[1]) continue;
                            for (int[] p3 : rowTop3[r3]) {
                                if (p3[1] == p1[1] || p3[1] == p2[1]) continue;
                                maxSum = Math.max(maxSum, (long) p1[0] + p2[0] + p3[0]);
                            }
                        }
                    }
                }
            }
        }
        return maxSum;
    }
}

var maximumValueSum = function(board) {
    const m = board.length;
    const n = board[0].length;
    const rowTop3 = [];
    for (let r = 0; r < m; r++) {
        const row = [];
        for (let c = 0; c < n; c++) {
            row.push([board[r][c], c]);
        }
        row.sort((a, b) => b[0] - a[0]);
        rowTop3.push(row.slice(0, 3));
    }
    let maxSum = -Infinity;
    for (let r1 = 0; r1 < m; r1++) {
        for (let r2 = r1 + 1; r2 < m; r2++) {
            for (let r3 = r2 + 1; r3 < m; r3++) {
                for (const [v1, c1] of rowTop3[r1]) {
                    for (const [v2, c2] of rowTop3[r2]) {
                        if (c2 === c1) continue;
                        for (const [v3, c3] of rowTop3[r3]) {
                            if (c3 === c1 || c3 === c2) continue;
                            const sum = v1 + v2 + v3;
                            if (sum > maxSum) maxSum = sum;
                        }
                    }
                }
            }
        }
    }
    return maxSum;
};
